      _saveDupes(map);
      return map[id] ?? 0;
    }

    // 서명 불일치 → 변조로 판단, 전체 초기화
    if (sig !== _signDupes(map)) {
      _saveDupes({});
      return 0;
    }

    return map[id] ?? 0;
  } catch {
    return 0;
