  /**
   * 이니셜 입력 UI 표시
   */
  private showInitialInputUI() {
    // 안내 텍스트
    this.add.text(200, 250, '이니셜 입력 (영어 대문자 3자)', {
      fontSize: '18px',
      color: '#ffffff',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 3
    }).setOrigin(0.5).setDepth(200);

    // HTML input 엘리먼트 생성
    const inputElement = document.createElement('input');
    inputElement.type = 'text';
    inputElement.maxLength = 3;
    inputElement.placeholder = 'ABC';
    inputElement.style.cssText = `
      position: absolute;
      left: 50%;
      top: 315px;
      transform: translateX(-50%);
      width: 120px;
      height: 40px;
      font-size: 24px;
      text-align: center;
      text-transform: uppercase;
      border: 3px solid #FFD700;
      border-radius: 8px;
      background: #000;
      color: #fff;
      font-weight: bold;
      letter-spacing: 8px;
    `;

    // 기존 이니셜이 있으면 미리 채우기
    const existingInitials = getUserInitials();
    if (existingInitials) {
      inputElement.value = existingInitials;
    }

    document.body.appendChild(inputElement);
    inputElement.focus();

    // 대문자만 입력되도록
    inputElement.addEventListener('input', (e) => {
      const target = e.target as HTMLInputElement;
      target.value = target.value.toUpperCase().replace(/[^A-Z]/g, '');
    });

    // 제출 버튼 텍스트
    const submitButtonText = this.add.text(200, 360, '랭킹 등록', {
      fontSize: '24px',
      color: '#00ff00',
      fontStyle: 'bold',
      stroke: '#000',
      strokeThickness: 4,
      padding: { x: 20, y: 10 }
    }).setOrigin(0.5).setInteractive().setDepth(200);

    // 에러 메시지 영역
    let errorText: Phaser.GameObjects.Text | null = null;

    // 제출 버튼 클릭
    submitButtonText.on('pointerdown', async () => {
      const initials = inputElement.value.trim().toUpperCase();

      // 검증
      if (initials.length !== 3) {
        if (errorText) errorText.destroy();
        errorText = this.add.text(200, 410, '정확히 3글자를 입력하세요', {
          fontSize: '16px',
          color: '#ff0000',
          fontStyle: 'bold',
          stroke: '#000',
          strokeThickness: 3
        }).setOrigin(0.5).setDepth(200);
        return;
      }

      if (!/^[A-Z]{3}$/.test(initials)) {
        if (errorText) errorText.destroy();
        errorText = this.add.text(200, 410, '영어 대문자만 입력하세요', {
          fontSize: '16px',
          color: '#ff0000',
          fontStyle: 'bold',
          stroke: '#000',
          strokeThickness: 3
        }).setOrigin(0.5).setDepth(200);
        return;
      }

      // 이니셜 저장
      setUserInitials(initials);

      // input 제거
      document.body.removeChild(inputElement);
      submitButtonText.destroy();
      if (errorText) errorText.destroy();

      // 랭킹 제출
      const submittingText = this.add.text(200, 300, '랭킹 제출 중...', {
        fontSize: '18px',
        color: '#ffff00',
        fontStyle: 'bold',
        stroke: '#000',
        strokeThickness: 3
      }).setOrigin(0.5).setDepth(200);

      try {
        // 캐릭터 타입 결정 (이미 init()에서 검증된 값 사용)
        const characterType = this.selectedCharId;

        // 세션이 완료될 때까지 대기 (대부분 이미 완료되어 있음)
        const sessionId = await this.sessionPromise;

        const result = await submitScore(
          this.score,
          this.difficulty,
          initials,
          {
            gameStartTime: this.gameStartTime,
            gameEndTime: realNow(),
            goldCollected: this.goldCollected,
            diamondCollected: this.diamondCollected,
            topazCollected: this.topazCollected,
            rainbowCollected: this.rainbowCollected,
          },
          characterType,
          sessionId
        );

        submittingText.destroy();

        // 순위 표시
        if (result.rank !== null) {
          this.add.text(200, 340, `🏆 전체 ${result.rank}위! 🏆`, {
            fontSize: '24px',
            color: '#FFD700',
            fontStyle: 'bold',
            stroke: '#000',
            strokeThickness: 3
          }).setOrigin(0.5).setDepth(200);
        }

        // 이니셜 표시
        this.add.text(200, 380, `${initials}`, {
          fontSize: '20px',
          color: '#00ff00',
          fontStyle: 'bold',
          stroke: '#000',
          strokeThickness: 3,
          letterSpacing: 4
        }).setOrigin(0.5).setDepth(200);

      } catch (error) {
        console.error('Failed to submit score:', error);
        submittingText.setText('❌ 랭킹 제출 실패');
        submittingText.setColor('#ff0000');
      }

      // 재시작 버튼 표시
      this.showRestartButton(true);
    });

    // Enter 키로도 제출 가능
    inputElement.addEventListener('keypress', (e) => {
      if (e.key === 'Enter') {
        submitButtonText.emit('pointerdown');
      }
    });
  }

  /**
   * 게임오버 시 SKOR 정제 수익 제출 및 화면 표시
   */
  /** 점수 브래킷별 게임당 SKOR 상한 (서버와 동일) */
  private getSkorBracketCap(score: number): number {
    if (score < 1000) return 40;
    if (score < 2000) return 70;
    if (score < 3000) return 90;
    return 110;
  }

  private async submitSkorOnGameOver(statusText: Phaser.GameObjects.Text) {
    // ── 낙관적 UI: 서버 응답 전에 예상 SKOR 즉시 계산 ──
    const rawSkor =
      this.goldCollected * 0.5 +
      this.diamondCollected * 1.5 +
      this.topazCollected * 3.5 +
      this.rainbowCollected * 10.0;
    const estimatedSkor = Math.floor(Math.min(rawSkor, this.getSkorBracketCap(this.score)));

    // floor 후 0이면 API 호출 없이 즉시 종료 (퀘스트 진행도도 없음)
    if (estimatedSkor <= 0) {
      statusText.setText('💰 +0 SKOR (아이템 없음)');
      statusText.setColor('#888888');
      return;
    }

    statusText.setText(`💰 +${estimatedSkor} SKOR 획득!`);
    statusText.setColor('#FFD700');

    // ── 백그라운드 API 호출: 실제 결과로 보정 ──
    try {
      const result: SkorSubmitResponse = await submitSkor({
        score: this.score,
        goldCollected: this.goldCollected,
        diamondCollected: this.diamondCollected,
        topazCollected: this.topazCollected,
        rainbowCollected: this.rainbowCollected,
      });

      if (!this.scene.isActive()) return;

      // 주간 캡 소진 또는 실제값이 예상과 다른 경우만 갱신
      if (result.weeklyCapRemaining <= 0 && result.totalSkorAdded === 0) {
        statusText.setText(`💰 주간 한도 도달 (SKOR 없음)`);
        statusText.setColor('#888888');
      } else if (result.totalSkorAdded !== estimatedSkor) {
        statusText.setText(`💰 +${result.totalSkorAdded} SKOR 획득!`);
      }

      // 퀘스트 달성 시 추가 알림 (항상 표시)
      if (result.questRewards.length > 0) {
        const questLabels: Record<string, string> = {
          gold: '금똥', diamond: '다이아', topaz: '토파즈', rainbow: '무지개',
        };
        const questText = result.questRewards
          .map(r => `${questLabels[r.quest] ?? r.quest} 퀘스트 +${r.reward}`)
          .join(' / ');
        this.add.text(200, statusText.y + 23, `🎯 ${questText}`, {
          fontSize: '13px',
          color: '#88ff88',
          stroke: '#000',
          strokeThickness: 2,
        }).setOrigin(0.5).setDepth(200);
      }
    } catch {
      // 실패해도 낙관적으로 보여준 숫자 유지 (정제 결과는 서버에서 처리됨)
    }
  }

  /**
   * 재시작 버튼 표시 (다시 하기 + 메인 메뉴) - 버튼 스타일
   * @param isNewRecord 새 기록 달성 여부 (SKOR 텍스트 위치에 따라 버튼 y 조정)
   */
  private showRestartButton(isNewRecord = false) {
    // 새 기록 시: SKOR 텍스트(y≈418) + 퀘스트(y≈441) 아래 배치
    // 일반 시: SKOR 텍스트(y≈380) + 퀘스트(y≈403) 아래 배치
    const retryY = isNewRecord ? 470 : 455;
    const menuY  = isNewRecord ? 548 : 535;

    // 다시 하기 버튼 배경
    const retryButtonBg = this.add.rectangle(200, retryY, 250, 70, 0x00aa00)
      .setOrigin(0.5)
      .setDepth(199)
      .setStrokeStyle(3, 0xffffff);

    // 다시 하기 버튼 텍스트
    const retryButtonText = this.add.text(200, retryY, '다시 하기', {
      fontSize: '22px',
      color: '#ffffff',
      fontStyle: 'bold'
    }).setOrigin(0.5).setDepth(200);

    // 다시 하기 버튼 인터랙티브 영역 (배경을 클릭 가능하게)
    retryButtonBg.setInteractive({ useHandCursor: true });

    // 메인 메뉴 버튼 배경
    const menuButtonBg = this.add.rectangle(200, menuY, 250, 70, 0x555555)
      .setOrigin(0.5)
      .setDepth(199)
      .setStrokeStyle(3, 0xffffff);

    // 메인 메뉴 버튼 텍스트
    const menuButtonText = this.add.text(200, menuY, '메인 메뉴', {
      fontSize: '22px',
      color: '#ffffff',
      fontStyle: 'bold'
    }).setOrigin(0.5).setDepth(200);

    // 메인 메뉴 버튼 인터랙티브 영역
    menuButtonBg.setInteractive({ useHandCursor: true });

    // 호버 효과 - 다시 하기 버튼
    retryButtonBg.on('pointerover', () => {
      retryButtonBg.setFillStyle(0x00ff00);
      retryButtonBg.setScale(1.05);
      retryButtonText.setScale(1.05);
    });
    retryButtonBg.on('pointerout', () => {
      retryButtonBg.setFillStyle(0x00aa00);
      retryButtonBg.setScale(1);
      retryButtonText.setScale(1);
    });

    // 호버 효과 - 메인 메뉴 버튼
    menuButtonBg.on('pointerover', () => {
      menuButtonBg.setFillStyle(0x777777);
      menuButtonBg.setScale(1.05);
      menuButtonText.setScale(1.05);
    });
    menuButtonBg.on('pointerout', () => {
      menuButtonBg.setFillStyle(0x555555);
      menuButtonBg.setScale(1);
      menuButtonText.setScale(1);
    });

    // 0.5초 지연 후 클릭 이벤트 활성화 (의도치 않은 즉시 클릭 방지)
    this.time.delayedCall(500, () => {
      // 다시 하기 버튼 클릭
      retryButtonBg.on('pointerdown', () => {
        // HTML input이 남아있으면 제거
        const existingInput = document.querySelector('input');
        if (existingInput) {
          document.body.removeChild(existingInput);
        }

        // 모든 사운드 정리
        this.sound.stopAll();
        // 플레이어 효과 정리
        if (this.player) {
          this.player.cleanupEffects();
        }

        // 같은 게임 모드와 난이도로 재시작
        this.scene.restart({ gameMode: this.gameMode, difficulty: this.difficulty });
      });

      // 메인 메뉴 버튼 클릭
      menuButtonBg.on('pointerdown', () => {
        // HTML input이 남아있으면 제거
        const existingInput = document.querySelector('input');
        if (existingInput) {
          document.body.removeChild(existingInput);
        }

        // 모든 사운드 정리
        this.sound.stopAll();
        // 플레이어 효과 정리
        if (this.player) {
          this.player.cleanupEffects();
        }

        // 모드 선택 씬으로 돌아가기
        this.scene.start('ModeSelectScene');
      });
    });
  }
}

import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI, SpecialPoopType } from './types';
import { MINER_PARAMS } from '../config/abilityParams';

/**
 * 광부 (SR) — 무지개똥 + 수집 보너스
 * 특수 똥 수집 시 +{specialBonus}점 / {rainbowInterval}점마다 무지개똥 스폰
 */
export class MinerAbility extends BaseAbility {
  private lastRainbowScore = 0;

  override onCollectSpecial(_type: SpecialPoopType): number {
    return MINER_PARAMS.specialBonus;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % MINER_PARAMS.rainbowInterval === 0 && score > this.lastRainbowScore) {
      this.lastRainbowScore = score;
      api.spawnRainbowPoop();
    }
  }
}

import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import { MAEHWA_PARAMS } from '../config/abilityParams';

/**
 * 매화 (SR) — 이동속도 +{speedBonus}px/s / {slashInterval}점마다 칼 베기 {slashCount}개
 * ★2: 특수 똥 수집 시 +{awake2SpecialBonus}점
 */
export class MaehwaAbility extends BaseAbility {
  private lastMaehwaScore = 0;

  override getPlayerSpeedBonus(): number {
    return MAEHWA_PARAMS.speedBonus;
  }

  // ★2+: 특수 똥 수집 시 +awake2SpecialBonus점
  override onCollectSpecial(_type: import('./types').SpecialPoopType): number {
    return this.awakeningLevel >= 2 ? MAEHWA_PARAMS.awake2SpecialBonus : 0;
  }

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (!api.isClassicMode) return;
    if (score % MAEHWA_PARAMS.slashInterval === 0 && score > this.lastMaehwaScore) {
      this.lastMaehwaScore = score;
      this.slashClosestPoops(MAEHWA_PARAMS.slashCount, api);
    }
  }

  private slashClosestPoops(count: number, api: GameSceneAPI): void {
    const active = api.poops
      .getChildren()
      .filter(p => {
        const sp = p as Phaser.Physics.Arcade.Sprite;
        return sp.active && sp.y < api.player.y;
      }) as Phaser.Physics.Arcade.Sprite[];

    active.sort((a, b) => {
      const da = Phaser.Math.Distance.Between(api.player.x, api.player.y, a.x, a.y);
      const db = Phaser.Math.Distance.Between(api.player.x, api.player.y, b.x, b.y);
      return da - db;
    });

    active.slice(0, count).forEach(poop => {
      this.drawSlashEffect(poop.x, poop.y, api);
      this.spawnPetals(poop.x, poop.y, api);
      poop.destroy();
    });
  }

  /** 가운데가 넓은 대각선(↗) 칼날 이펙트 */
  private drawSlashEffect(cx: number, cy: number, api: GameSceneAPI): void {
    const gfx = api.scene.add.graphics().setDepth(120);

    // 칼날: fillPoints로 ↗ 방향 마름모꼴 (끝은 뾰족, 중앙은 넓음)
    const len = 26; // 반길이
    const wid = 7;  // 중앙 최대 반폭
    // ↗ 방향 slash: (cx-len, cy+len) → (cx+len, cy-len) 축
    gfx.fillStyle(0xff3366, 0.9);
    gfx.fillPoints([
      new Phaser.Geom.Point(cx - len, cy + len),          // 좌하 끝
      new Phaser.Geom.Point(cx - wid * 0.4, cy + wid),    // 좌상 측면
      new Phaser.Geom.Point(cx + len, cy - len),          // 우상 끝
      new Phaser.Geom.Point(cx + wid * 0.4, cy - wid),    // 우하 측면
    ], true);

    // 외곽 흰색 글로우
    gfx.lineStyle(3, 0xffffff, 0.5);
    gfx.lineBetween(cx - len, cy + len, cx + len, cy - len);

    api.scene.tweens.add({
      targets: gfx,
      alpha: 0,
      duration: 300,
      onComplete: () => gfx.destroy(),
    });
  }

  /** 붉은 매화 잎 여러 개 낙화 */
  private spawnPetals(cx: number, cy: number, api: GameSceneAPI): void {
    const PETAL_COUNT = 7;
    for (let i = 0; i < PETAL_COUNT; i++) {
      const petal = api.scene.add.graphics().setDepth(121);
      // 초기 위치: 파괴된 똥 주변 랜덤
      const startX = cx + Phaser.Math.Between(-12, 12);
      const startY = cy + Phaser.Math.Between(-12, 12);
      petal.setPosition(startX, startY);

      // 작은 타원형 꽃잎
      const petalW = Phaser.Math.Between(4, 7);
      const petalH = Phaser.Math.Between(7, 11);
      petal.fillStyle(0xff2255, 0.85 + Math.random() * 0.15);
      petal.fillEllipse(0, 0, petalW, petalH);
      petal.setAngle(Phaser.Math.Between(0, 360));

      // 바람에 날리며 낙하
      api.scene.tweens.add({
        targets: petal,
        x: startX + Phaser.Math.Between(-25, 25),
        y: startY + Phaser.Math.Between(30, 60),
        angle: petal.angle + Phaser.Math.Between(-120, 120),
        alpha: 0,
        duration: Phaser.Math.Between(400, 700),
        ease: 'Sine.easeIn',
        onComplete: () => petal.destroy(),
      });
    }
  }
}

